package org.apache.commons.cli;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for OptionBuilder.create(String)
 */
public class OptionBuilder_create_TriageGen2Test {

    @Test
    public void testCreateWithValidShortOpt() {
        // Testing the standard flow of building an option via the builder pattern
        Option option = OptionBuilder.withLongOpt("help")
                .withDescription("display help")
                .isRequired()
                .hasArg()
                .withArgName("file")
                .create("h");

        assertNotNull("Option should not be null", option);
        assertEquals("h", option.getOpt());
        assertEquals("help", option.getLongOpt());
        assertEquals("display help", option.getDescription());
        assertTrue("Option should be required", option.isRequired());
        assertTrue("Option should have an argument", option.hasArg());
        assertEquals("file", option.getArgName());
    }












}

