package org.apache.commons.cli;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for OptionBuilder.create(String)
 */
public class OptionBuilder_create_TriageGen2Test {









    @Test
    public void testBuilderResetAfterCreate() {
        // First creation
        OptionBuilder.withLongOpt("first").create("a");

        // Second creation - verify that OptionBuilder.reset() worked 
        // and properties from the first call don't leak into the second
        Option option2 = OptionBuilder.create("b");

        assertNotNull(option2);
        assertEquals("b", option2.getOpt());
        assertNull("Long opt should have been reset", option2.getLongOpt());
    }




}

